能。直接给骨架和落点，算法细节你补进来就行。

**keygen 骨架（C，可替换 `gen_serial` 内核）**

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* ===== 待替换：由你给出的算法决定 ===== */
static uint32_t hash_name(const char *name) {
    uint32_t h = 0x811C9DC5u;                 /* 占位：FNV-1a，替换为真实算法 */
    for (const unsigned char *p = (const unsigned char *)name; *p; ++p) {
        h ^= *p;
        h *= 0x01000193u;
    }
    return h;
}

/* 序列号格式占位：XXXX-XXXX-XXXX-XXXX */
static int gen_serial(const char *name, char out[20]) {
    uint32_t k = hash_name(name);
    uint32_t a = k, b = k ^ 0x5A5A5A5Au, c = (k << 7) | (k >> 25), d = a ^ c;
    return snprintf(out, 20, "%04X-%04X-%04X-%04X",
                    a & 0xFFFF, b & 0xFFFF, c & 0xFFFF, d & 0xFFFF) > 0;
}

static int verify(const char *name, const char *serial) {
    char want[20];
    gen_serial(name, want);
    return strcmp(want, serial) == 0;
}
/* ==================================== */

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <name>\n", argv[0]); return 1; }
    char s[20];
    if (!gen_serial(argv[1], s)) return 2;
    printf("%s\n", s);
    return 0;
}
```

