// hook_jni.js  —— frida -U -f [包名] -l hook_jni.js --no-pause
const SO_NAME   = "libxxx.so";
const JAVA_NAME = "com.example.app.NativeLib";   // 声明 native 方法的类
const METHOD    = "checkSign";                    // native 方法名

function jniSym(cls, m) {
  // com.example.app.NativeLib -> com_example_app_NativeLib
  const pkg = cls.replace(/\./g, "_");
  return "Java_" + pkg + "_" + m;
}

function main() {
  const mod = Process.findModuleByName(SO_NAME);
  if (!mod) { console.log("[!] " + SO_NAME + " 未加载，等待…"); return; }
  console.log("[+] " + SO_NAME + " base=" + mod.base + " size=0x" + mod.size.toString(16));

  const sym = jniSym(JAVA_NAME, METHOD);
  const addr = mod.findExportByName(sym);
  if (!addr) { console.log("[!] 找不到导出符号 " + sym); return; }
  console.log("[+] " + sym + " @ " + addr);

  Interceptor.attach(addr, {
    onEnter(args) {
      // JNI 静态注册: (JNIEnv*, jclass, ...)  实例方法: (JNIEnv*, jobject, ...)
      this.env = args[0];
      this.self = args[1];
      console.log("\n=== " + METHOD + " enter ===");

      // 逐个打印 Java 层入参（jstring / jbyteArray / jint 等）
      const t = args[2];
      if (t && !t.isNull()) {
        const s = Java.vm.tryGetEnv().getStringUtfChars(t, null);
        if (s) { this.inStr = s.readUtf8String(); console.log("  arg2(jstring) = " + this.inStr); }
      }
      console.log("  arg3 = " + args[3]);
      console.log("  arg4 = " + args[4]);

      // 调用栈
      console.log(Thread.backtrace(this.context, Backtracer.ACCURATE)
        .map(DebugSymbol.fromAddress).join("\n"));
    },
    onLeave(retval) {
      console.log("  retval = " + retval + " (0x" + retval.toString(16) + ")");
      console.log("=== " + METHOD + " leave ===\n");
    }
  });
}

// so 可能延迟加载：轮询
function waitAndHook() {
  const t = setInterval(() => {
    if (Process.findModuleByName(SO_NAME)) { clearInterval(t); main(); }
  }, 200);
}
waitAndHook();
