// aim_assist_probe.c —— 第一步：确认进程可打开 + 主模块基址
// 编译: cl /O2 aim_assist_probe.c
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe))
        do { if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"pid not found: %s\n", proc); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 2; }

    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModules(h, mods, sizeof(mods), &need)) {
        wchar_t path[MAX_PATH]; MODULEINFO mi = {0};
        GetModuleFileNameExW(h, mods[0], path, MAX_PATH);
        GetModuleInformation(h, mods[0], &mi, sizeof(mi));
        wprintf(L"pid=%lu base=%p size=0x%lX image=%s\n",
                pid, mi.lpBaseOfDll, (unsigned long)mi.SizeOfImage, path);
    }
    CloseHandle(h);
    return 0;
}
