#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int main() {
    const wchar_t* proc = L"[进程名].exe";
    const wchar_t* mod  = L"[模块名].exe";   // Unity/UE 常见为 GameAssembly.dll / [游戏名]-Win64-Shipping.exe

    DWORD pid = FindPid(proc);
    if (!pid) { printf("pid not found\n"); return 1; }
    printf("pid = %lu\n", pid);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess failed = %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, mod);
    printf("base = 0x%llX\n", (unsigned long long)base);

