```javascript
// scan_coin.js
const KNOWN_VALUE = 12345; // 把界面上显示的金币数填这里

function findModuleRange(name) {
  const m = Process.findModuleByName(name);
  if (!m) return null;
  return { base: m.base, end: m.base.add(m.size), name: m.name };
}

setImmediate(() => {
  const mods = Process.enumerateModules().map(m => `${m.name}@${m.base} size=${m.size}`);
  console.log('[+] modules:\n' + mods.join('\n'));

  const rwRanges = Process.enumerateRanges('rw-').map(r =>
    ({ base: r.base, size: r.size }));
  console.log('[+] rw- ranges: ' + rwRanges.length);

  let total = 0;
  const hits = [];
  for (const r of rwRanges) {
    // 分块扫描，避免大块一次读完
    const CHUNK = 0x100000;
    for (let off = 0; off < r.size; off += CHUNK) {
      const len = Math.min(CHUNK, r.size - off);
      try {
        const buf = r.base.add(off).readByteArray(len);
        if (!buf) continue;
        const u8 = new Uint8Array(buf);
        const dv = new DataView(u8.buffer);
        for (let i = 0; i + 4 <= u8.length; i += 4) {
          if (dv.getInt32(i, true) === KNOWN_VALUE) {
            hits.push(r.base.add(off + i));
          }
        }
      } catch (e) {}
    }
  }
  total = hits.length;
  console.log(`[+] int32 hits for ${KNOWN_VALUE}: ${total}`);
  hits.slice(0, 64).forEach(a => console.log('    ' + a));
  globalThis.__coinHits = hits;
});
```

