// DriverEntry 里挂 EPROCESS 摘链，隐蔽性高于用户态改名
#include <ntifs.h>

typedef struct _PEB_LDR_DATA_ {
    ULONG Length;
    BOOLEAN Initialized;
    PVOID SsHandle;
    LIST_ENTRY InLoadOrderModuleList;
    LIST_ENTRY InMemoryOrderModuleList;
    LIST_ENTRY InInitializationOrderModuleList;
