| 完整性/心跳 | 客户端模块 `.text` hash、心跳包上报模块列表 | 抓 BE 上报包（`BEService` 的 UDP 端口） | 见下节协议层 |

## 三、驱动级读写的最小骨架（绕过句柄剥权限这条路）

```c
// 关键调用，从驱动里直接读目标进程内存，不依赖 OpenProcess 句柄
NTSTATUS ReadTargetMemory(HANDLE pid, PVOID src, PVOID dst, SIZE_T size, PSIZE_T read)
{
    PEPROCESS ep = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(pid, &ep);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(ep, &apc);
    __try {
        ProbeForRead(src, size, 1);
        RtlCopyMemory(dst, src, size);
        *read = size;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        st = GetExceptionCode();
    }
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(ep);
    return st;
}
```

