// drv_readwrite.c —— WDM 驱动，MmCopyVirtualMemory 实现任意进程读写
#include <ntifs.h>
#include <ntddk.h>

#define DEV_NAME    L"\\Device\\rwdrv"
#define SYMLINK     L"\\DosDevices\\rwdrv"
#define IOCTL_READ  0x80002000
#define IOCTL_WRITE 0x80002004

typedef struct _RW_REQ {
    HANDLE pid;
    PVOID  addr;
    PVOID  buf;
    ULONG  size;
} RW_REQ, *PRW_REQ;

static NTSTATUS ReadWrite(PEPROCESS target, PVOID addr, PVOID buf, ULONG size, BOOLEAN write)
{
    PEPROCESS src = write ? PsGetCurrentProcess() : target;
    PEPROCESS dst = write ? target : PsGetCurrentProcess();
    PVOID s = write ? buf : addr;
    PVOID d = write ? addr : buf;
    SIZE_T done = 0;
    return MmCopyVirtualMemory(src, s, dst, d, size, KernelMode, &done);
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION st = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS status = STATUS_INVALID_PARAMETER;
    ULONG code = st->Parameters.DeviceIoControl.IoControlCode;
    ULONG inlen = st->Parameters.DeviceIoControl.InputBufferLength;
    PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
    PEPROCESS proc = NULL;

    if ((code == IOCTL_READ || code == IOCTL_WRITE) && inlen >= sizeof(RW_REQ) && req) {
        if (NT_SUCCESS(PsLookupProcessByProcessId(req->pid, &proc))) {
            status = ReadWrite(proc, req->addr, req->buf, req->size, code == IOCTL_WRITE);
            ObDereferenceObject(proc);
