**目标参数（占位，缺哪个填哪个）**：`[进程名]` `[模块名]`（UE4 客户端 `UE4Game.exe` / 手游 `libUE4.so` / `[包名]`），先从基址和这两个全局容器入手：

```c
// 1. 模块基址：从 PEB 走，不依赖 EnumProcessModules 的可疑调用
#include <winternl.h>
#pragma comment(lib, "ntdll.lib")
uint64_t GetModuleBase(HANDLE hProc, const wchar_t* name) {
    PROCESS_BASIC_INFORMATION pbi{};
    NtQueryInformationProcess(hProc, ProcessBasicInformation, &pbi, sizeof(pbi), nullptr);
    uint64_t peb = (uint64_t)pbi.PebBaseAddress;
    uint64_t ldr = 0;
    ReadProcessMemory(hProc, (LPCVOID)(peb + 0x18), &ldr, 8, nullptr);   // PEB->Ldr
    uint64_t head = ldr + 0x10;                                          // InLoadOrderModuleList
    uint64_t cur = 0;
    ReadProcessMemory(hProc, (LPCVOID)head, &cur, 8, nullptr);
    while (cur != head) {
        uint64_t dllBase = 0; uint16_t len = 0; wchar_t buf[64]{};
        ReadProcessMemory(hProc, (LPCVOID)(cur + 0x30), &dllBase, 8, nullptr);
        ReadProcessMemory(hProc, (LPCVOID)(cur + 0x58), &len, 2, nullptr);
        ReadProcessMemory(hProc, (LPCVOID)(cur + 0x60), buf, min(len, 126), nullptr);
        if (_wcsicmp(buf, name) == 0) return dllBase;
        ReadProcessMemory(hProc, (LPCVOID)cur, &cur, 8, nullptr);
    }
    return 0;
}
```

