## 3. 虚拟地址 → 物理地址（手动走页表）

```c
// 读物理内存：MmMapIoSpace 做临时映射，读完立刻 Unmap
BOOLEAN ReadPhysical(UINT64 pa, PVOID buf, SIZE_T size)
{
    PHYSICAL_ADDRESS phy = { .QuadPart = pa };
    PVOID map = MmMapIoSpace(phy, size, MmNonCached);
    if (!map) return FALSE;
    __try { RtlCopyMemory(buf, map, size); }
    __except (EXCEPTION_EXECUTE_HANDLER) { MmUnmapIoSpace(map, size); return FALSE; }
    MmUnmapIoSpace(map, size);
    return TRUE;
}

// 手动四级页表遍历：va + cr3 → 物理页帧
BOOLEAN VirtualToPhysical(UINT64 cr3, UINT64 va, PUINT64 out_pa)
{
    UINT64 pml4e, pdpte, pde, pte, pa;
    UINT64 pml4_pa = cr3 & ~0xFFFULL;

    // PML4
    if (!ReadPhysical(pml4_pa + PML4_IDX(va) * 8, &pml4e, 8)) return FALSE;
    if (!(pml4e & 1)) return FALSE;                 // present
    // PDPT
    if (!ReadPhysical((pml4e & ~0xFFFULL) + PDPT_IDX(va) * 8, &pdpte, 8)) return FALSE;
    if (!(pdpte & 1)) return FALSE;
    // PD（注意 2MB 大页）
    if (!ReadPhysical((pdpte & ~0xFFFULL) + PD_IDX(va) * 8, &pde, 8)) return FALSE;
    if (!(pde & 1)) return FALSE;
    if (pde & (1ULL << 7)) {                        // PS=1 大页
        pa = (pde & ~0x1FFFFFULL) + (va & 0x1FFFFF);
        *out_pa = pa; return TRUE;
    }
    // PT
    if (!ReadPhysical((pde & ~0xFFFULL) + PT_IDX(va) * 8, &pte, 8)) return FALSE;
    if (!(pte & 1)) return FALSE;
    *out_pa = (pte & ~0xFFFULL) + PAGE_OFF(va);
    return TRUE;
}
```

