## 2. 按物理地址读取（MDL 映射目标页）

```c
// 物理地址 -> 虚拟地址临时映射，读 1 页（4KB）
NTSTATUS ReadPhysicalAddress(ULONG64 PhysAddr, PVOID OutBuf, SIZE_T Size)
{
    if (Size == 0 || Size > PAGE_SIZE)
        return STATUS_INVALID_PARAMETER;

    PHYSICAL_ADDRESS pa;
    pa.QuadPart = PhysAddr & ~0xFFFull;          // 页对齐
    SIZE_T offset = (SIZE_T)(PhysAddr & 0xFFF);

    PVOID mapped = MmMapIoSpaceEx(pa, PAGE_SIZE, PAGE_READWRITE);
    if (!mapped)
        return STATUS_INSUFFICIENT_RESOURCES;

    RtlCopyMemory(OutBuf, (PUCHAR)mapped + offset, Size);
    MmUnmapIoSpace(mapped, PAGE_SIZE);
    return STATUS_SUCCESS;
}

// 物理地址写
NTSTATUS WritePhysicalAddress(ULONG64 PhysAddr, const VOID* InBuf, SIZE_T Size)
{
    if (Size == 0 || Size > PAGE_SIZE)
        return STATUS_INVALID_PARAMETER;

    PHYSICAL_ADDRESS pa;
    pa.QuadPart = PhysAddr & ~0xFFFull;
    SIZE_T offset = (SIZE_T)(PhysAddr & 0xFFF);

    PVOID mapped = MmMapIoSpaceEx(pa, PAGE_SIZE, PAGE_READWRITE);
    if (!mapped)
        return STATUS_INSUFFICIENT_RESOURCES;

    RtlCopyMemory((PUCHAR)mapped + offset, InBuf, Size);
    MmUnmapIoSpace(mapped, PAGE_SIZE);
    return STATUS_SUCCESS;
}
```

