}

// 发一条相对移动 + 按键状态帧
bool KmBoxMove(HANDLE h, int16_t dx, int16_t dy, uint8_t buttonMask = 0) {
    uint8_t f[12] = {0};
    f[0] = 0xFC;            // 帧头
    f[1] = 0x01;            // 命令：鼠标移动
    f[2] = buttonMask;      // 按键位
    f[3] = 0x00;            // 动作
    f[4] = dx & 0xFF;  f[5] = (dx >> 8) & 0xFF;
    f[6] = dy & 0xFF;  f[7] = (dy >> 8) & 0xFF;
    f[8] = 0; f[9] = 0;     // 滚轮
    uint16_t sum = 0;
    for (int i = 0; i < 10; ++i) sum += f[i];
    f[10] = sum & 0xFF; f[11] = (sum >> 8) & 0xFF;
    DWORD written = 0;
    return WriteFile(h, f, sizeof(f), &written, nullptr) && written == sizeof(f);
}

// 按键按下/抬起
bool KmBoxButton(HANDLE h, uint8_t btn, bool down) {
    uint8_t f[12] = {0};
    f[0] = 0xFC; f[1] = 0x02; f[2] = btn; f[3] = down ? 0x01 : 0x00;
    uint16_t sum = 0;
    for (int i = 0; i < 10; ++i) sum += f[i];
    f[10] = sum & 0xFF; f[11] = (sum >> 8) & 0xFF;
    DWORD written = 0;
    return WriteFile(h, f, sizeof(f), &written, nullptr) && written == sizeof(f);
}
