// Windows x64，用户态只读摸底：模块基址 + 候选 UWorld
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (snap == INVALID_HANDLE_VALUE) return 0;
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { DWORD pid = pe.th32ProcessID; CloseHandle(snap); return pid; }
    CloseHandle(snap);
    return 0;
}

static uintptr_t ModuleBase(DWORD pid, const wchar_t* mod, DWORD* outSize = nullptr) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (snap == INVALID_HANDLE_VALUE) return 0;
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) {
            base = (uintptr_t)me.modBaseAddr;
            if (outSize) *outSize = me.modBaseSize;
            break;
        }
    CloseHandle(snap);
    return base;
}

int wmain() {
    const wchar_t* PROC = L"[进程名].exe";
    const wchar_t* MOD  = L"[模块名].exe";

    DWORD pid = FindPid(PROC);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed %lu\n", GetLastError()); return 1; }

    DWORD msize = 0;
    uintptr_t base = ModuleBase(pid, MOD, &msize);
    wprintf(L"pid=%lu base=%p size=0x%lX\n", pid, (void*)base, msize);

    // 已知：UWorld 是主模块上的一个指针，偏移先用占位符 [UWORLD_RVA]
    const uintptr_t UWORLD_RVA = 0x[UWORLD_RVA];
    uintptr_t slot = base + UWORLD_RVA, uworld = 0;
    SIZE_T n = 0;
    if (ReadProcessMemory(h, (LPCVOID)slot, &uworld, sizeof(uworld), &n) && uworld) {
        wprintf(L"slot=%p uworld=%p\n", (void*)slot, (void*)uworld);
        // 校验：UWorld 头 8 字节通常是指向自身的 vtable，落在主模块 .rdata 范围内
        uintptr_t vtbl = 0;
        if (ReadProcessMemory(h, (LPCVOID)uworld, &vtbl, 8, &n))
