// 特征码扫描：找 UWorld 槽（先用 x64dbg 在真实进程里确认一段唯一字节序列再替换 PATTERN）
std::vector<uintptr_t> AobScan(HANDLE h, uintptr_t base, DWORD msize,
                               const std::vector<int>& pat /*-1 = 通配*/) {
    std::vector<uint8_t> buf(msize);
    SIZE_T n = 0;
    if (!ReadProcessMemory(h, (LPCVOID)base, buf.data(), msize, &n)) return {};
    std::vector<uintptr_t> hits;
    for (size_t i = 0; i + pat.size() <= n; ++i) {
        bool ok = true;
        for (size_t j = 0; j < pat.size(); ++j)
            if (pat[j] >= 0 && buf[i + j] != (uint8_t)pat[j]) { ok = false; break; }
        if (ok) hits.push_back(base + i);
    }
    return hits;
}
