// mem_probe.cpp — MSVC x64, 链接无需额外库
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t ModuleBase(DWORD pid, const wchar_t* mod, DWORD* sizeOut) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) {
                base = (uintptr_t)me.modBaseAddr;
                if (sizeOut) *sizeOut = me.modBaseSize;
                break;
            }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].dll";

    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"pid not found: %s\n", proc); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION
                          | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    DWORD modSize = 0;
    uintptr_t base = ModuleBase(pid, mod, &modSize);
    wprintf(L"pid=%lu base=%p size=0x%X\n", pid, (void*)base, modSize);

    // 多级指针链示例： [[base + 0x[偏移1]] + 0x[偏移2]] + 0x[偏移3]
    uintptr_t addr = base + 0x[偏移1];
    for (int level = 0; level < 3; ++level) {
        uintptr_t next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)addr, &next, sizeof(next), nullptr)) {
            wprintf(L"rpm failed at %p (lvl %d) err=%lu\n", (void*)addr, level, GetLastError());
            CloseHandle(h);
            return 1;
        }
        addr = next + (level == 0 ? 0x[偏移2] : (level == 1 ? 0x[偏移3] : 0x[偏移4]));
    }
    wprintf(L"target addr = %p\n", (void*)addr);

    // 先 dump 原值，改前留回滚
    int orig = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &orig, sizeof(orig), nullptr);
    wprintf(L"orig value = %d\n", orig);

    CloseHandle(h);
    return 0;
}
