// 拿模块基址（x64 下 PEB->Ldr 遍历更稳，这里先用快照版）
DWORD_PTR GetModuleBase(HANDLE hProc, const wchar_t* modName) {
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, GetProcessId(hProc));
    if (hSnap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me = { sizeof(me) };
    DWORD_PTR base = 0;
    if (Module32FirstW(hSnap, &me)) {
        do {
            if (_wcsicmp(me.szModule, modName) == 0) { base = (DWORD_PTR)me.modBaseAddr; break; }
        } while (Module32NextW(hSnap, &me));
    }
    CloseHandle(hSnap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* procName = L"[进程名].exe";
    const wchar_t* modName  = L"[模块名].exe";
    HANDLE hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, /*pid=*/0);
    if (!hProc) { wprintf(L"OpenProcess fail %lu\n", GetLastError()); return 1; }
    DWORD_PTR base = GetModuleBase(hProc, modName);
    wprintf(L"base = 0x%llX\n", (unsigned long long)base);

    // 多级指针链解析: [[base + off1] + off2] + off3
    DWORD_PTR off1 = 0x[偏移1], off2 = 0x[偏移2], off3 = 0x[偏移3];
    DWORD_PTR p1 = 0, p2 = 0, val = 0;
    ReadProcessMemory(hProc, (LPCVOID)(base + off1), &p1, sizeof(p1), NULL);
    ReadProcessMemory(hProc, (LPCVOID)(p1 + off2),    &p2, sizeof(p2), NULL);
    ReadProcessMemory(hProc, (LPCVOID)(p2 + off3),    &val, sizeof(val), NULL);
    wprintf(L"resolved = 0x%llX\n", (unsigned long long)val);

    CloseHandle(hProc);
    return 0;
}
