```c
// maps_scan.c —— push 到设备上跑，或编译成 frida 用 Process.enumerateModules()
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

unsigned long find_so_base(const char* pid, const char* soname) {
    char path[64]; snprintf(path, sizeof(path), "/proc/%s/maps", pid);
    FILE* f = fopen(path, "r");
    char line[512]; unsigned long base = 0;
    while (fgets(line, sizeof(line), f)) {
        if (strstr(line, soname) && strstr(line, "r-xp")) { // 找可执行段
            sscanf(line, "%lx", &base);
            break;
        }
    }
    fclose(f);
    return base;
}
