```

## 二、锁头三段式：取实体 → 算角度 → 写视角

### 1. 读实体与骨骼（用户态读写模块，最小可用）

```cpp
// 基础句柄 + 读写封装
HANDLE hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, [pid]);
uint64_t base = GetModuleBase(hProc, L"[模块名]"); // Toolhelp32Snapshot 枚举

template<typename T>
T RPM(uint64_t addr) {
    T v{};
    ReadProcessMemory(hProc, (LPCVOID)addr, &v, sizeof(T), nullptr);
    return v;
}
template<typename T>
void WPM(uint64_t addr, T v) {
    WriteProcessMemory(hProc, (LPVOID)addr, &v, sizeof(T), nullptr);
}
```

### 2. 取矩阵与本地相机（W2S 必需）

```cpp
struct Matrix4x4 { float m[4][4]; };

uint64_t viewMatrixPtr = base + [视角矩阵偏移];   // 多级链：先解析指针链再读矩阵
Matrix4x4 vm = RPM<Matrix4x4>(viewMatrixPtr);
```

### 3. 世界坐标 → 屏幕坐标（W2S）

```cpp
bool WorldToScreen(const Vec3& w, const Matrix4x4& m, Vec2& out, int w, int h) {
    float clipW = m.m[3][0]*w.x + m.m[3][1]*w.y + m.m[3][2]*w.z + m.m[3][3];
    if (clipW < 0.01f) return false;
    float clipX = m.m[0][0]*w.x + m.m[0][1]*w.y + m.m[0][2]*w.z + m.m[0][3];
    float clipY = m.m[1][0]*w.x + m.m[1][1]*w.y + m.m[1][2]*w.z + m.m[1][3];
    float ndcX = clipX / clipW, ndcY = clipY / clipW;
    out.x = (ndcX * 0.5f + 0.5f) * w;
    out.y = (1.f - (ndcY * 0.5f + 0.5f)) * h;
    return true;
}
```

### 4. 找最近、可见、FOV 内的头骨点 → 算目标角

```cpp
struct Actor { uint64_t addr; Vec3 head; bool visible; };
std::vector<Actor> actors = GetActors(); // 遍历实体列表，取骨骼[头骨索引]

Vec3 camPos = GetCameraPos();  // 相机世界坐标（矩阵或 Cam 结构里取）
Vec2 screenCenter = { sw * 0.5f, sh * 0.5f };

Actor* best = nullptr; float bestDist = FLT_MAX;
for (auto& a : actors) {
    if (!a.visible) continue;                  // 可见性：射线检测/遮挡位
    Vec2 sp;
    if (!WorldToScreen(a.head, vm, sp, sw, sh)) continue;
    float d = std::hypot(sp.x - screenCenter.x, sp.y - screenCenter.y);
    if (d < FOV_PIXELS && d < bestDist) { bestDist = d; best = &a; }
}
```

### 5. 目标 → 平滑角度 + 后坐力补偿 + 写视角

```cpp
Vec3 dir = {best->head.x - camPos.x,
            best->head.y - camPos.y,
            best->head.z - camPos.z};

float targetYaw   = atan2f(dir.y, dir.x) * 180.f / PI;
float targetPitch = atan2f(-dir.z, sqrtf(dir.x*dir.x + dir.y*dir.y)) * 180.f / PI;

// 平滑（一帧只走一部分，拟人化，避免瞬移被抓特征）
Vec3 cur = RPM<Vec3>(base + [视角偏移]);
cur.x += (targetPitch - cur.x) * SMOOTH;   // 通常是 pitch/yaw 顺序，按实际结构对
cur.y += (targetYaw   - cur.y) * SMOOTH;
cur.x += RecoilComp();                      // 后坐力累积量，从武器状态结构读
WPM<Vec3>(base + [视角偏移], cur);
```

